data = ""

cout_A = 0
cout_C = 0
cout_G = 0
cout_T = 0

for char in data:
    if char == "A":
        cout_A += 1
    elif char == "C":
        cout_C += 1
    elif char == "G":
        cout_G += 1
    elif char == "T":
        cout_T += 1
    else:
        break

print(cout_A, cout_C, cout_G, cout_T)